# ROOM-12: overlap handling
f=$(mktemp)
BOOKINGS=$f bash bin/book A 0900 1000 standup >/dev/null
BOOKINGS=$f bash bin/book A 0930 1030 dup >/dev/null 2>&1 && { echo "overlap accepted"; fail=1; }
BOOKINGS=$f bash bin/book A 0800 0901 dup >/dev/null 2>&1 && { echo "overlap(before) accepted"; fail=1; }
BOOKINGS=$f bash bin/book A 0915 0945 dup >/dev/null 2>&1 && { echo "contained accepted"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "overlap must not write"; fail=1; }
BOOKINGS=$f bash bin/book A 1000 1100 next >/dev/null 2>&1 || { echo "adjacent after rejected"; fail=1; }
BOOKINGS=$f bash bin/book A 0800 0900 prev >/dev/null 2>&1 || { echo "adjacent before rejected"; fail=1; }
BOOKINGS=$f bash bin/book B 0900 1000 other >/dev/null 2>&1 || { echo "other room rejected"; fail=1; }
[ "$(wc -l < "$f")" -eq 4 ] || { echo "valid bookings count"; fail=1; }
rm -f "$f"
exit $fail

